use xiom.io;

use xiom.string;
fn parse_date(date: Str) -> Result[(Int, Int, Int), Str] {
  if string.str_len(date) != 10 {
    return Err("Date must be exactly DD/MM/YYYY");
  }
  let slash1 = string.str_slice(date, 2, 3);
  let slash2 = string.str_slice(date, 5, 6);
  if slash1 != "/" || slash2 != "/" {
    return Err("Date must use / separators");
  }
  let day_str = string.str_slice(date, 0, 2);
  let month_str = string.str_slice(date, 3, 5);
  let year_str = string.str_slice(date, 6, 10);
  let day = string.str_to_int(day_str)?;
  let month = string.str_to_int(month_str)?;
  let year = string.str_to_int(year_str)?;
  if day < 1 || day > 31 { return Err("Day out of range"); }
  if month < 1 || month > 12 { return Err("Month out of range"); }
  if year < 1900 || year > 2100 { return Err("Year out of range"); }
  return Ok((day, month, year));
}

fn main() -> Int {
  match parse_date("25/12/2024") {
    Ok((d, m, y)) => { return y; }
    Err(_) => { return -1; }
  }
}
